<?php
require_once dirname(__DIR__,2).'/app/bootstrap.php';require_owner();$uid=current_user_id();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'read');if(!in_array($status,['read','closed'],true))$status='read';db()->prepare('UPDATE enquiries SET status=:s WHERE id=:id AND listing_id IN (SELECT id FROM listings WHERE owner_user_id=:u)')->execute([':s'=>$status,':id'=>$id,':u'=>$uid]);flash('success','Enquiry status updated.');redirect(app_path('owner/inbox.php'));}$s=db()->prepare('SELECT e.*,l.name listing_name FROM enquiries e JOIN listings l ON l.id=e.listing_id WHERE l.owner_user_id=:u ORDER BY e.created_at DESC LIMIT 100');$s->execute([':u'=>$uid]);$items=$s->fetchAll();$ownerTitle='Customer enquiries';include __DIR__.'/_header.php';?><div class="admin-panel"><div class="panel-heading"><div><span class="eyebrow">CUSTOMER MESSAGES</span><h2>Enquiries for your businesses</h2></div></div><?php if($items): ?><div class="table-wrap"><table class="admin-table"><thead><tr><th>Contact</th><th>Business</th><th>Message</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($items as $e): ?><tr><td><strong><?= h($e['sender_name']) ?></strong><small><a href="mailto:<?= h($e['sender_email']) ?>"><?= h($e['sender_email']) ?></a><?= $e['sender_phone']?'<br>'.h($e['sender_phone']):'' ?></small></td><td><?= h($e['listing_name']) ?></td><td><?= h(text_excerpt($e['message'],180)) ?></td><td><?= h(ucfirst($e['status'])) ?></td><td><form method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$e['id'] ?>"><select name="status"><option value="read">Mark read</option><option value="closed">Close</option></select><button class="table-action">Save</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="empty-admin">No enquiries yet.</p><?php endif; ?></div><?php include __DIR__.'/_footer.php';?>
